                        CALLBACK_PARMETER: {
                            APPROVAL_PRC_TYPE: "APPROVAL_REQUEST"
                        }
                    });
                }
            });




        	var params = {};
            doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectInitAppLine', {
                HOUSE_CODE: Sepoa.info.HOUSE_CODE,
                COMPANY_CODE: Sepoa.info.COMPANY_CODE,
                DIVISION_KEY: 'REQ'
            }, function(so) {
                if (so.status == 1) {
                    var sf = new SepoaFormater(so.result[0]);
                    params.data = [{
                        SEAL_SORT: 'E',
                        APP_LINE_SEQ: '0',
                        APP_METHOD: '01',
                        APP_USER_ID: Sepoa.info.ID,
                        APP_USER_NAME: sf.dataMap.NAME_LOC,
                        SELLER_CODE: Sepoa.info.COMPANY_CODE,
                        POSITION: sf.dataMap.POSITION,
                        DEPARTMENT_NAME: sf.dataMap.DEPARTMENT_NAME_LOC,
                        EMPLOYEE_NO: sf.dataMap.EMPLOYEE_NO[0],
                        MANAGE_NO_LIST: $selectedExtList
                    }];
                } else {
                    Alert("요청자 정보를 조회하지 못했습니다.");
                }
            }, false);

           	var reqSealHeaderInfo = formObj.getFormData();
           	var useNum = reqSealHeaderInfo["SEAL_USE_TYPE"];
          	var sealArr = [];
           	gridObj.forEachRowA(function(id) {
				var smdNo = gridObj.cells(id, gridObj.getColIndexById('SMD_NUMBER')).getValue()
				if (deleteRows.indexOf(smdNo) == -1) {
					sealArr.push(gridObj.cells(id, gridObj.getColIndexById('MANAGE_NUMBER')).getValue());
				}
			});

			let targetCode = 'AP994';
			doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectInitAppLine', {DIVISION_KEY: 'USESEAL_DESIGNATE', USE_NUM : useNum, SEAL_ARR : sealArr, code: targetCode}, function(so) {
				if (so.status == 1) {
            		var sf = new SepoaFormater(so.result[0]);
	            	var sfList = sf.getArrayMap();

	            	for(let i in sfList) {
                    	let approver = sfList[i]; 
                    	approver.NOT_CHANGE = true;
                    	params.data.push(approver);
                   	}
            	} else {
            		Alert("사용인감 초기 결재자 세팅에 실패하였습니다.")
            	}
			}, false);

            var width = Math.min(SUX.root.innerWidth * 0.7, 1280);
            var height = Math.min((SUX.root.innerHeight - 100) * 0.9, 800);
            PopupOpenPost('/UxDefault/ApprovalLine/Popup.sux', params, function(data) {
                var params = {};
                params.data = data;
                params.callbackParams = callbackParams;

                doApprovalProcess(params);
            }, width, height, Sepoa.cache.text.get('SLM_221.APPLINE_SETTING_SECL'));




            var config = {
                url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                on: {
                    callback: function(res) {
                        if (res.status == "1") {
                            Alert(Sepoa.cache.text.get('MESSAGE.0001'));

                            if (Sepoa.request.SMR_NUMBER) {
                                linkTo('SLM_510', '/Seal/Document/External/Request/SealExternalRequestLayout.sux', 'undefined', Sepoa.cache.text.get('SLM_501.REQUEST_LIST'));
                            } else if (smrStatus == 'T' && moveFlag == 'Y') {
                                linkTo('SLM_510', '/Seal/Document/External/Request/SealExternalRequestLayout.sux', 'undefined', Sepoa.cache.text.get('SLM_501.REQUEST_LIST'));
                                SUX.root.getContentsCell(window).close();
                            } else {
                                doBack();
                            }
                        } else {
                            Alert(res.message);
                        }
                    }
                }
            }

            // $reqSealInfo.CONFIRM_STATUS = callbackParams.LEGAL_PRC_TYPE;

            var serviceData = {
                REQ_EXT_INFO: $reqExtInfo,
                REQ_SEAL_INFO: $reqExtInfo,
                DOCUMENT_LIST: $documentList,
                APP_LINE: params.data.approver,
                APP_INFO: {
                    APP_COMMENT: params.data.comment
                }
            };

            var params = {
                module: "ext.req",
                action: "doRequestService",
                CONNECTION: "TRANSACTION",
                CURRENT_PRC: "APPROVAL",
                PARAMETER: JSON.stringify(serviceData)
            }

            sUtils.multipart.send(config, params);



            //$documentList 는 요청시 저장되는 gridObj의 데이터
